/**
 * Wire the conversion error log's "Print" button to the browser print dialog.
 *
 * @module     tool_courseuplift/printbutton
 * @copyright  2026 Vernon Spain
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * Attach a click handler that opens the browser print dialog.
 *
 * @param {string} selector CSS selector for the print button.
 */
export const init = (selector) => {
    const button = document.querySelector(selector);
    if (!button) {
        return;
    }
    button.addEventListener('click', () => window.print());
};
